import{_ as o,o as t,c as a,ae as r}from"./chunks/framework.Dn6zxbF8.js";const u=JSON.parse('{"title":"Hierarchy position is referenced by a bare parent field","description":"","frontmatter":{"id":"6310044131","title":"Hierarchy position is referenced by a bare parent field","state":"Approved","created":"2026-07-09T00:00:00.000Z","tags":["naming","multi-tenancy","hierarchy","api-design"],"category":"Platform"},"headers":[],"relativePath":"adrs/6310044131/README.md","filePath":"adrs/6310044131/README.md"}'),n={name:"adrs/6310044131/README.md"};function i(s,e,c,d,l,h){return t(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="hierarchy-position-is-referenced-by-a-bare-parent-field" tabindex="-1">Hierarchy position is referenced by a bare parent field <a class="header-anchor" href="#hierarchy-position-is-referenced-by-a-bare-parent-field" aria-label="Permalink to &quot;Hierarchy position is referenced by a bare parent field&quot;">​</a></h1><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p><a href="./../4761776210/README.html">ADR#4761776210</a> attaches every resource to exactly one node of its tenant&#39;s hierarchy. Each service now needs a field on its resources that references that node, and without a shared convention each service will invent its own (<code>folder</code>, <code>scope</code>, <code>container</code>, <code>parentId</code>), which makes cross-service reading and tooling needlessly hard.</p><p>Two worries shaped the naming:</p><p><strong>Ambiguity with kinship.</strong> Systems also have parent-child relationships between resources of the same kind (a session spawned by a session, an agent delegated by an agent). Could <code>parent</code> mean two things?</p><p><strong>Collisions.</strong> <code>container</code> collides with OCI containers on any platform that runs workloads; <code>scope</code> and <code>location</code> carry established meanings in cloud APIs (auth scopes, regions).</p><p>Industry evidence, verified against primary sources (linked below):</p><ul><li><strong>Google Cloud</strong>: the Project resource has a field named <code>parent</code>, documented as &quot;A reference to a parent Resource. eg., <code>organizations/123</code> or <code>folders/876</code>&quot;, plus a <code>projects.move</code> method (&quot;Move a project to another place in your resource hierarchy, under a new resource parent&quot;).</li><li><strong>AWS</strong>: Organizations speaks Parent throughout: <code>ListParents</code> (&quot;Lists the root or organizational units (OUs) that serve as the immediate parent of the specified child&quot;), <code>MoveAccount(AccountId, SourceParentId, DestinationParentId)</code>. Its docs also state the single canonical parent outright: &quot;In the current release, a child can have only a single parent.&quot;</li><li><strong>Azure</strong>: the ManagementGroup resource carries <code>properties.details.parent</code> (<code>ParentGroupInfo</code>: &quot;The ID of the parent management group&quot;, with <code>id</code>, <code>name</code>, <code>displayName</code>).</li><li><strong>Kubernetes HNC</strong>: &quot;The parent is defined by the <code>.spec.parent</code> field&quot; of each namespace&#39;s <code>HierarchyConfiguration</code> object.</li></ul><p><strong>An honest caveat about this evidence.</strong> The four attestations above sit on org-structure nodes (OUs, folders, management groups, projects), not on arbitrary resources attached inside the structure, which is our case. For placed leaf resources the picture differs: GCP leaves carry no stored parent field (the position is encoded in the resource name), AWS leaves have no hierarchy (tags), and Kubernetes, the one platform with a stored position field on every object, calls it <code>namespace</code>. The convention still transfers to our case on three narrower grounds:</p><ol><li>Movability is the real dividing line, not org-versus-resource: GCP&#39;s stored <code>parent</code> field appears exactly on things that move (Project, Folder) and not on things that don&#39;t. Our resources are movable, so the Project precedent is a case match.</li><li><code>parent</code> is Google&#39;s universal request vocabulary for placing any resource, not just org nodes: every AIP-133 create is <code>Create&lt;Thing&gt;(parent: ...)</code> for books and topics as much as folders.</li><li>The honest counter-candidate from the leaf-resource world, <code>namespace</code>, names a flat concept; importing it onto a recursive tenant-drawn tree would mislead the engineers it is meant to help.</li></ol><p>GCP&#39;s and Azure&#39;s parent values are typed references, so the value states what kind of node the parent is.</p><p>Compound alternatives were considered and each carries a wart: <code>parent_id</code> does not say which parent; <code>parent_container</code> reintroduces the OCI collision; <code>parent_folder</code> introduces vocabulary the hierarchy ADR does not use; and <code>parent_node</code>, though it now uses the right word, says in the field name what the field&#39;s type already says. The ambiguity a compound would prevent does not occur in practice: ambiguity lives inside a single schema, and no schema carries both a hierarchy position and unqualified kinship.</p><h2 id="resolution" tabindex="-1">Resolution <a class="header-anchor" href="#resolution" aria-label="Permalink to &quot;Resolution&quot;">​</a></h2><p>Chosen option: a bare <code>parent</code> field, because it matches the verified industry convention for movable resources and the feared ambiguity cannot arise under the qualification rule below.</p><ol><li>On any resource, the field <code>parent</code> refers to position: the node of the tenant&#39;s hierarchy the resource is attached to. It has no other meaning, on any resource, in any service.</li><li>Kinship between resources is always qualified, never bare: <code>parentSessionId</code>, <code>parentAgentId</code>, <code>sourceParentId</code>. A bare <code>parent</code> holding kinship is a review defect.</li><li>Parent values are self-describing, so a value read in isolation says what it points at. Two mechanisms deliver that and both apply: the field&#39;s type, <code>trogon.hierarchy.v1alpha1.NodeId</code>, and the resource id prefix carried inside the value, <code>node_01h9x</code>. Our prefix convention (<a href="./../4860595695/README.html">ADR#4860595695</a>) is what GCP achieves with a collection segment (<code>folders/876</code>); it is the same goal reached by the spelling this ecosystem already uses, so parent values take the prefix form and not the path form. The value names one node and never encodes ancestry.</li><li>The spellings <code>parentId</code> and <code>parent_id</code> are disallowed, for a reason internal to our own naming pattern rather than imported taste. Every id-suffixed reference field we write is <code>&lt;Type&gt;Id</code>: the word before the suffix names a resource type (<code>agentId</code>, <code>sessionId</code>, <code>rubricId</code>). &quot;Parent&quot; is not a type; it is a role, and a position may point at a node of any kind, which is its entire point. So the two valid shapes are: role-named bare <code>parent</code> for position, and role-plus-type <code>parent&lt;Type&gt;Id</code> for kinship (<code>parentSessionId</code>, where Session is the type). <code>parentId</code> is a role plus suffix with no type, fitting neither pattern, so it cannot be written. This mirrors actual Google practice, which mixes bare <code>parent</code> with type-named <code>book_id</code> in one request without contradiction. Weight note: the load-bearing rule of this ADR is kinship qualification (rule 2); this spelling rule is a consistency rule on top of it.</li><li>When ids are wrapper messages rather than bare strings, the <code>Id</code> suffix stays in the field name. Rule 4&#39;s two shapes then read as <code>NodeId parent</code> for position and <code>SessionId parent_session_id</code> for kinship. The name repeats what the type says on purpose: consumers of the JSON form often have no schema and see only the key (<code>parentSessionId</code>), so the key itself must say that the value points at a session rather than embedding one. Position needs no such signal, because a parent is never inline content.</li></ol><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><ul><li>Engineers arriving from GCP, AWS, Azure, or Kubernetes read the field correctly on sight.</li><li>Grep for <code>parent[^A-Z_]</code> finds every position reference across services; qualified kinship never pollutes the result.</li><li><code>parent</code> is where accountability is anchored: attaching to a node is an authorized write, so who answers for the node answers for what hangs off it. Resources do not carry an <code>owner</code> field to restate that, per <a href="./../4761776210/README.html">ADR#4761776210</a>. The field still grants nothing on its own; policy evaluation reads it as input.</li><li>Moving a resource is a change of <code>parent</code>, which keeps move APIs uniform (<code>sourceParent</code>, <code>destinationParent</code>) across services.</li><li>The rule is enforced in schema tooling, not review vigilance: the protobuf lint pipeline accepts exactly two shapes and rejects the rest. A field named exactly <code>parent</code> must reference a hierarchy node; a field matching <code>parent&lt;Type&gt;Id</code> is kinship and must carry the qualifier; every other <code>parent*</code> spelling (including <code>parentId</code> and <code>parent_id</code>) is rejected (the machine-checkable analog of Google&#39;s <code>google.api.resource_reference</code> annotations on parent fields).</li><li>Domains that own a tree of same-kind resources qualify with their own type (<code>parentTaskId</code>, <code>parentCommentId</code>). The hierarchy service&#39;s own events are the one near-bare use (<code>parentId</code> on a node), which is consistent: there the parent is the position.</li><li>Foreign protocols keep their names at the boundary. If an external standard uses bare <code>parent</code> for kinship, adapters translate at the edge; this ADR governs our stored schemas and events only.</li></ul><h2 id="links" tabindex="-1">Links <a class="header-anchor" href="#links" aria-label="Permalink to &quot;Links&quot;">​</a></h2><ul><li><a href="./../4761776210/README.html">ADR#4761776210</a>: Resource hierarchy via untyped recursive nodes</li><li><a href="./../4860595695/README.html">ADR#4860595695</a>: Human-Readable IDs</li><li><a href="./../1394819661/README.html">ADR#1394819661</a>: Resource Is the Generic Noun, Object Is a Runtime Term</li><li><a href="https://docs.cloud.google.com/resource-manager/reference/rest/v3/projects" target="_blank" rel="noreferrer">GCP Project resource: <code>parent</code> field and <code>projects.move</code></a></li><li><a href="https://docs.aws.amazon.com/organizations/latest/APIReference/API_ListParents.html" target="_blank" rel="noreferrer">AWS Organizations ListParents (&quot;a child can have only a single parent&quot;)</a></li><li><a href="https://docs.aws.amazon.com/organizations/latest/APIReference/API_MoveAccount.html" target="_blank" rel="noreferrer">AWS Organizations MoveAccount (<code>SourceParentId</code>, <code>DestinationParentId</code>)</a></li><li><a href="https://learn.microsoft.com/en-us/rest/api/managementgroups/management-groups/get" target="_blank" rel="noreferrer">Azure Management Groups Get (<code>properties.details.parent</code>)</a></li><li><a href="https://github.com/kubernetes-sigs/hierarchical-namespaces/blob/master/docs/user-guide/concepts.md" target="_blank" rel="noreferrer">Kubernetes HNC concepts (<code>.spec.parent</code>)</a></li></ul>',19)])])}const f=o(n,[["render",i]]);export{u as __pageData,f as default};
